1	package consensus
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"testing"
10	)
11	
12	func newTestNodeCap(t *testing.T, keys []testKey, maxTxs, capacity uint64) (*Node, string) {
13		t.Helper()
14		dir := t.TempDir()
15		vals := make([][]byte, len(keys))
16		for i, k := range keys {
17			vals[i] = k.pub
18		}
19		n, err := New(dir, Config{Seed: []byte("test-seed-cap"), Validators: vals, MaxTxsPerBlock: maxTxs, PoolCapacity: capacity})
20		if err != nil {
21			t.Fatal(err)
22		}
23		return n, dir
24	}
25	
26	// 容量进入配置查询并随状态持久化；省略时为 0（不限制）。
27	func TestCapacityConfigAndQuery(t *testing.T) {
28		keys := genKeys(t, 4)
29		n, dir := newTestNodeCap(t, keys, 10, 3)
30		cfg := n.Config()
31		if cfg.PoolCapacity != 3 || cfg.MaxTxsPerBlock != 10 {
32			t.Fatalf("config = %+v, want capacity 3 maxTxs 10", cfg)
33		}
34		n2, err := Open(dir)
35		if err != nil {
36			t.Fatal(err)
37		}
38		if got := n2.Config().PoolCapacity; got != 3 {
39			t.Fatalf("restored capacity = %d, want 3", got)
40		}
41	
42		// 省略容量：保持现有行为（不限制）。
43		n3, _ := newTestNode(t, keys, 10)
44		if got := n3.Config().PoolCapacity; got != 0 {
45			t.Fatalf("default capacity = %d, want 0 (unlimited)", got)
46		}
47		for i := 0; i < 20; i++ {
48			tx := NewTransaction(keys[0].priv, uint64(i+1), []byte(fmt.Sprintf("t%d", i)), 1, 1000)
49			if _, err := n3.Submit(tx); err != nil {
50				t.Fatalf("unlimited pool rejected tx %d: %v", i, err)
51			}
52		}
53	}
54	
55	// 满池时费用不更高的新交易被 pool-full 拒绝：池不变、不留历史、腾出位置后可重新提交。
56	// 费用更高时挤出费用最低者，结果给出被挤出标识，旧交易保留完整内容并显示 dropped。
57	func TestCapacityEviction(t *testing.T) {
58		keys := genKeys(t, 4)
59		n, _ := newTestNodeCap(t, keys, 10, 2)
60	
61		a := NewTransaction(keys[0].priv, 1, []byte("a"), 5, 100)
62		b := NewTransaction(keys[1].priv, 1, []byte("b"), 3, 100)
63		for _, tx := range []*Transaction{a, b} {
64			if _, err := n.Submit(tx); err != nil {
65				t.Fatal(err)
66			}
67		}
68	
69		// 费用低于池中最低：拒绝，池保持不变，且不留任何历史。
70		cheap := NewTransaction(keys[2].priv, 1, []byte("cheap"), 2, 100)
71		if _, err := n.Submit(cheap); reason(err) != ReasonPoolFull {
72			t.Fatalf("cheap tx got %v, want %s", err, ReasonPoolFull)
73		}
74		if _, err := n.Tx(cheap.ID()); reason(err) != ReasonUnknownTx {
75			t.Fatalf("rejected tx left history: %v", err)
76		}
77		if info, _ := n.Tx(a.ID()); info.Status != StatusQueued {
78			t.Fatalf("rejected submit changed pool: a = %s", info.Status)
79		}
80		if info, _ := n.Tx(b.ID()); info.Status != StatusQueued {
81			t.Fatalf("rejected submit changed pool: b = %s", info.Status)
82		}
83	
84		// 费用更高：挤出费用最低的 b。
85		d := NewTransaction(keys[2].priv, 1, []byte("d"), 4, 100)
86		res, err := n.Submit(d)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if res.EvictedID != b.ID() || res.TxID != d.ID() || res.ReplacedID != "" {
91			t.Fatalf("eviction result wrong: %+v", res)
92		}
93	
94		// 被挤出的交易保留完整内容，显示 dropped/pool-capacity/发生轮次，
95		// 不带确认块或替换交易关联。
96		info, err := n.Tx(b.ID())
97		if err != nil {
98			t.Fatal(err)
99		}
100		if info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
101			t.Fatalf("dropped tx wrong: %+v", info)
102		}
103		if info.BlockHeight != 0 || info.BlockID != "" || info.ReplacedBy != "" {
104			t.Fatalf("dropped tx must not carry block/replace links: %+v", info)
105		}
106		if info.Tx == nil || string(info.Tx.Content) != "b" || info.Tx.Fee != 3 {
107			t.Fatalf("dropped tx content not preserved: %+v", info.Tx)
108		}
109		// 不再占用位置：账户待处理列表为空。
110		if acct := n.Account(keys[1].pub); len(acct.Pending) != 0 {
111			t.Fatalf("dropped tx still pending: %+v", acct)
112		}
113	
114		// 再次提交完全相同的旧交易仍按重复拒绝。
115		if _, err := n.Submit(NewTransaction(keys[1].priv, 1, []byte("b"), 3, 100)); reason(err) != ReasonDuplicate {
116			t.Fatalf("resubmit dropped tx got %v, want %s", err, ReasonDuplicate)
117		}
118	
119		// 同发送者同序号的新交易按普通提交规则竞争位置：费用足够高即可挤出别人。
120		b2 := NewTransaction(keys[1].priv, 1, []byte("b2"), 10, 100)
121		res, err = n.Submit(b2)
122		if err != nil {
123			t.Fatal(err)
124		}
125		if res.EvictedID != d.ID() || res.ReplacedID != "" {
126			t.Fatalf("fresh same-seq tx should compete normally: %+v", res)
127		}
128	
129		// 被挤出的交易不能再用于登记候选。
130		if _, err := n.Propose(); err != nil {
131			t.Fatal(err)
132		}
133		if _, err := n.RegisterCandidate(1, []string{d.ID()}); reason(err) != ReasonTxNotInPool {
134			t.Fatalf("dropped tx in candidate got %v, want %s", err, ReasonTxNotInPool)
135		}
136	}
137	
138	// 同费时淘汰标识字典序最大者；新交易费用相同且标识更小时才能挤出，否则 pool-full。
139	func TestCapacityEvictionTieBreak(t *testing.T) {
140		keys := genKeys(t, 4)
141		n, _ := newTestNodeCap(t, keys, 10, 2)
142	
143		a := NewTransaction(keys[0].priv, 1, []byte("a"), 5, 100)
144		b := NewTransaction(keys[1].priv, 1, []byte("b"), 5, 100)
145		n.Submit(a)
146		n.Submit(b)
147		victim := a.ID()
148		if b.ID() > victim {
149			victim = b.ID()
150		}
151	
152		// 构造两笔同费交易：一笔标识小于淘汰对象（可挤出），一笔大于（被拒绝）。
153		var smaller, larger *Transaction
154		for i := 0; smaller == nil || larger == nil; i++ {
155			tx := NewTransaction(keys[2].priv, uint64(i+1), []byte(fmt.Sprintf("c%d", i)), 5, 100)
156			if tx.ID() < victim && smaller == nil {
157				smaller = tx
158			}
159			if tx.ID() > victim && larger == nil {
160				larger = tx
161			}
162		}
163	
164		res, err := n.Submit(smaller)
165		if err != nil {
166			t.Fatalf("same-fee smaller-id tx should evict: %v", err)
167		}
168		if res.EvictedID != victim {
169			t.Fatalf("evicted %s, want lexicographically largest %s", res.EvictedID, victim)
170		}
171	
172		// 池中现为幸存者与新交易（同费）：同费但标识更大的交易不能挤出。
173		curVictim := a.ID()
174		if curVictim == victim {
175			curVictim = b.ID()
176		}
177		if smaller.ID() > curVictim {
178			curVictim = smaller.ID()
179		}
180		if larger.ID() < curVictim {
181			t.Fatal("test setup: larger tx id must exceed current victim")
182		}
183		if _, err := n.Submit(larger); reason(err) != ReasonPoolFull {
184			t.Fatalf("same-fee larger-id tx got %v, want %s", err, ReasonPoolFull)
185		}
186		if _, err := n.Tx(larger.ID()); reason(err) != ReasonUnknownTx {
187			t.Fatalf("rejected tx left history: %v", err)
188		}
189	}
190	
191	// 满池时合法的加费替换不增加计数、可执行且不淘汰其他交易；被未决候选引用的交易仍禁止替换。
192	func TestCapacityReplacementWhenFull(t *testing.T) {
193		keys := genKeys(t, 4)
194		n, _ := newTestNodeCap(t, keys, 10, 1)
195	
196		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
197		if _, err := n.Submit(a); err != nil {
198			t.Fatal(err)
199		}
200		// 满池替换：不淘汰任何交易。
201		ahi := NewTransaction(keys[0].priv, 1, []byte("ahi"), 2, 100)
202		res, err := n.Submit(ahi)
203		if err != nil {
204			t.Fatalf("replacement on full pool must succeed: %v", err)
205		}
206		if res.ReplacedID != a.ID() || res.EvictedID != "" {
207			t.Fatalf("replacement must not evict: %+v", res)
208		}
209		// 计数不变：池仍满，新交易仍需竞争。
210		b := NewTransaction(keys[1].priv, 1, []byte("b"), 1, 100)
211		if _, err := n.Submit(b); reason(err) != ReasonPoolFull {
212			t.Fatalf("got %v, want %s", err, ReasonPoolFull)
213		}
214	
215		// 被未决候选引用的交易仍禁止替换。
216		p, err := n.Propose()
217		if err != nil {
218			t.Fatal(err)
219		}
220		if len(p.TxIDs) != 1 || p.TxIDs[0] != ahi.ID() {
221			t.Fatalf("proposal = %v, want [ahi]", p.TxIDs)
222		}
223		locked := NewTransaction(keys[0].priv, 1, []byte("locked"), 99, 100)
224		if _, err := n.Submit(locked); reason(err) != ReasonProposalLocked {
225			t.Fatalf("replacing proposed tx got %v, want %s", err, ReasonProposalLocked)
226		}
227	}
228	
229	// 被未决候选引用的交易受保护：占位但不可淘汰；轮次结束后只解除保护、仍占位置。
230	func TestCapacityProtection(t *testing.T) {
231		keys := genKeys(t, 4)
232		n, _ := newTestNodeCap(t, keys, 10, 1)
233	
234		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
235		n.Submit(a)
236		if _, err := n.Propose(); err != nil { // a 进入本地提议，受保护
237			t.Fatal(err)
238		}
239	
240		// 池中唯一交易受保护：任何费用的全新交易都无可淘汰者。
241		b := NewTransaction(keys[1].priv, 1, []byte("b"), 1000, 100)
242		if _, err := n.Submit(b); reason(err) != ReasonPoolFull {
243			t.Fatalf("got %v, want %s", err, ReasonPoolFull)
244		}
245	
246		// 主动结束轮次：a 回到排队（未到期，仍占位置），保护解除。
247		if _, err := n.EndRound(); err != nil {
248			t.Fatal(err)
249		}
250		if info, _ := n.Tx(a.ID()); info.Status != StatusQueued {
251			t.Fatalf("a after EndRound = %s, want queued", info.Status)
252		}
253		res, err := n.Submit(b)
254		if err != nil {
255			t.Fatalf("unprotected tx should be evictable: %v", err)
256		}
257		if res.EvictedID != a.ID() {
258			t.Fatalf("evicted %s, want %s", res.EvictedID, a.ID())
259		}
260		if info, _ := n.Tx(a.ID()); info.Status != StatusDropped || info.DropRound != 2 {
261			t.Fatalf("a should be dropped in round 2: %+v", info)
262		}
263	}
264	
265	// 共享交易只计一笔：多候选引用不重复计数；胜出确认后释放位置。
266	func TestCapacitySharedTxCountsOnce(t *testing.T) {
267		keys := genKeys(t, 4)
268		n, _ := newTestNodeCap(t, keys, 10, 2)
269	
270		shared := NewTransaction(keys[0].priv, 1, []byte("shared"), 1, 100)
271		other := NewTransaction(keys[1].priv, 1, []byte("other"), 1, 100)
272		n.Submit(shared)
273		n.Submit(other)
274		local, _ := n.Propose() // 本地提议含两笔
275		if len(local.TxIDs) != 2 {
276			t.Fatalf("local proposal = %v, want both txs", local.TxIDs)
277		}
278		// 竞争候选只含 shared：shared 被两个候选引用，仍只算一笔（池计数 2，已满）。
279		if _, err := n.RegisterCandidate(1, []string{shared.ID()}); err != nil {
280			t.Fatal(err)
281		}
282		c := NewTransaction(keys[2].priv, 1, []byte("c"), 1000, 100)
283		if _, err := n.Submit(c); reason(err) != ReasonPoolFull {
284			t.Fatalf("protected pool got %v, want %s", err, ReasonPoolFull)
285		}
286	
287		// 确认本地提议：两笔交易确认，位置全部释放。
288		confirmByVotes(t, n, keys, local.BlockID)
289		if _, err := n.Submit(c); err != nil {
290			t.Fatalf("confirmation must free slots: %v", err)
291		}
292		d := NewTransaction(keys[3].priv, 1, []byte("d"), 1, 100)
293		if _, err := n.Submit(d); err != nil {
294			t.Fatalf("second freed slot: %v", err)
295		}
296	}
