298	// 已确认、被替换、过期与被挤出的历史均不占位置。
299	func TestCapacityHistoryDoesNotCount(t *testing.T) {
300		keys := genKeys(t, 4)
301		n, _ := newTestNodeCap(t, keys, 10, 1)
302	
303		// 确认释放位置。
304		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
305		n.Submit(a)
306		p, _ := n.Propose()
307		confirmByVotes(t, n, keys, p.BlockID)
308	
309		// 被替换不占位置：替换后计数仍为 1。
310		b := NewTransaction(keys[1].priv, 1, []byte("b"), 1, 100)
311		n.Submit(b)
312		bhi := NewTransaction(keys[1].priv, 1, []byte("bhi"), 2, 100)
313		if _, err := n.Submit(bhi); err != nil {
314			t.Fatalf("replacement must not grow count: %v", err)
315		}
316		c := NewTransaction(keys[2].priv, 1, []byte("c"), 5, 3) // 进入轮次 3 时到期
317		res, err := n.Submit(c)                                 // 池满：挤出 bhi
318		if err != nil || res.EvictedID != bhi.ID() {
319			t.Fatalf("eviction after replacement: %+v %v", res, err)
320		}
321	
322		// 过期释放位置：c 在进入轮次 3 时失效。
323		d := NewTransaction(keys[3].priv, 1, []byte("d"), 1, 100)
324		if _, err := n.Submit(d); reason(err) != ReasonPoolFull {
325			t.Fatalf("full pool got %v, want %s", err, ReasonPoolFull)
326		}
327		if _, err := n.EndRound(); err != nil { // 轮次 2
328			t.Fatal(err)
329		}
330		if _, err := n.EndRound(); err != nil { // 轮次 3：c 到期
331			t.Fatal(err)
332		}
333		if info, _ := n.Tx(c.ID()); info.Status != StatusExpired {
334			t.Fatalf("c = %s, want expired", info.Status)
335		}
336		if _, err := n.Submit(d); err != nil {
337			t.Fatalf("expiry must free slot: %v", err)
338		}
339	}
