341	// 淘汰不推进已确认序号；留下缺口时账户查询指出最早缺口，后续序号保留但不能越过缺口打包。
342	func TestCapacityEvictionLeavesGap(t *testing.T) {
343		keys := genKeys(t, 4)
344		n, _ := newTestNodeCap(t, keys, 10, 2)
345	
346		s1 := NewTransaction(keys[0].priv, 1, []byte("s1"), 1, 100)
347		s2 := NewTransaction(keys[0].priv, 2, []byte("s2"), 2, 100)
