361		// s2 不能越过缺口被打包。
362		p, err := n.Propose()
363		if err != nil {
364			t.Fatal(err)
365		}
366		if len(p.TxIDs) != 1 || p.TxIDs[0] != x.ID() {
367			t.Fatalf("proposal = %v, want only x (s2 blocked by gap)", p.TxIDs)
368		}
369		confirmByVotes(t, n, keys, p.BlockID)
370		acct = n.Account(keys[0].pub)
371		if acct.ConfirmedSequence != 0 || acct.Gap != 1 || len(acct.Pending) != 1 {
372			t.Fatalf("gap must survive unrelated confirmation: %+v", acct)
373		}
