518	// 确定性：相同初始配置与输入顺序产生相同的接收决定、淘汰对象与后续确认结果。
519	func TestCapacityDeterminism(t *testing.T) {
520		keys := genKeys(t, 4)
521		run := func() ([]string, []string) {
522			vals := make([][]byte, len(keys))
523			for i, k := range keys {
524				vals[i] = append([]byte(nil), k.pub...)
525			}
526			n, err := New(t.TempDir(), Config{Seed: []byte("cap-det"), Validators: vals, MaxTxsPerBlock: 3, PoolCapacity: 2})
527			if err != nil {
528				t.Fatal(err)
529			}
530			var decisions []string
531			submit := func(tx *Transaction) {
532				res, err := n.Submit(tx)
533				if err != nil {
534					decisions = append(decisions, "reject:"+reason(err))
535					return
536				}
537				decisions = append(decisions, "accept:"+res.TxID+":"+res.EvictedID+":"+res.ReplacedID)
538			}
539			for r := 1; r <= 3; r++ {
540				submit(NewTransaction(keys[r%4].priv, uint64(r), []byte(fmt.Sprintf("c%d", r)), uint64((r*7)%13)+1, 100))
541				submit(NewTransaction(keys[(r+1)%4].priv, 1, []byte(fmt.Sprintf("d%d", r)), uint64(r), 100))
542				submit(NewTransaction(keys[(r+2)%4].priv, uint64(r), []byte(fmt.Sprintf("e%d", r)), uint64(r*3), 100))
543				p, _ := n.Propose()
544				confirmByVotes(t, n, keys, p.BlockID)
545			}
546			var blocks []string
547			for _, b := range n.st2Blocks() {
548				blocks = append(blocks, b.ID)
549			}
550			return decisions, blocks
551		}
552		d1, b1 := run()
553		d2, b2 := run()
554		if fmt.Sprint(d1) != fmt.Sprint(d2) {
555			t.Fatalf("accept/evict decisions differ:\n%v\n%v", d1, d2)
556		}
557		if fmt.Sprint(b1) != fmt.Sprint(b2) {
558			t.Fatalf("confirmed blocks differ:\n%v\n%v", b1, b2)
559		}
560	}
