84		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 30, 100)
85		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100)
86		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
87		b2 := NewTransaction(keys[1].priv, 2, []byte("b2"), 20, 100)
88		for _, tx := range []*Transaction{a1, a2, b1, b2} {
89			if _, err := n.Submit(tx); err != nil {
90				t.Fatal(err)
91			}
92		}
93	
94		want := []string{b1.ID(), a1.ID(), a2.ID()}
95		p := assertProposalOrder(t, n, want)
96		if wantID := BlockID(1, 1, "", want); p.BlockID != wantID {
97			t.Fatalf("block id = %s, want %s", p.BlockID, wantID)
98		}
99		// 未选入的乙2 保持等待打包，已选入的等待投票；已确认序号不受影响。
100		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{
101			a1.ID(): "waiting-vote", a2.ID(): "waiting-vote",
102		})
103		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{
104			b1.ID(): "waiting-vote", b2.ID(): "waiting-pack",
105		})
106		info, err := n.Tx(b2.ID())
107		if err != nil {
108			t.Fatal(err)
109		}
110		if info.Status != StatusQueued {
111			t.Fatalf("b2 status = %s, want queued", info.Status)
112		}
113	}
114	
115	// craftTxWithID 通过变换内容构造一笔交易，使其标识相对 ref 满足字典序要求
116	// （less 为 true 时要求标识更小）。用于确定性构造同费用比较场景。
117	func craftTxWithID(t *testing.T, priv ed25519.PrivateKey, seq, fee uint64, ref string, less bool) *Transaction {
118		t.Helper()
119		for i := 0; ; i++ {
120			tx := NewTransaction(priv, seq, []byte(fmt.Sprintf("tie-%d", i)), fee, 100)
121			if (tx.ID() < ref) == less {
122				return tx
123			}
124			if i > 10000 {
125				t.Fatal("cannot craft transaction with desired id ordering")
126			}
127		}
128	}
129	
130	// 同费用比较只发生在交易实际具备入选条件时：
131	// 刚成为可选的后续交易与另一账户的下一笔同费用，按标识字典序取较小者；
132	// 尚未具备条件的交易不能凭较小标识提前占位。
133	func TestProposeTieBreakOnlyWhenEligible(t *testing.T) {
134		keys := genKeys(t, 4)
135	
136		// 甲1 费用最高先入选，甲2 随即具备条件并与乙1 同费用：
137		// 甲2 标识更小时必须凭字典序排在乙1 前，不能因刚具备条件而固定靠后。
138		t.Run("newly eligible wins tie by smaller id", func(t *testing.T) {
139			n, _ := newTestNode(t, keys, 4)
140			a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 100, 100)
141			b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
142			a2 := craftTxWithID(t, keys[0].priv, 2, 50, b1.ID(), true)
143			for _, tx := range []*Transaction{a1, a2, b1} {
144				if _, err := n.Submit(tx); err != nil {
145					t.Fatal(err)
146				}
147			}
148			assertProposalOrder(t, n, []string{a1.ID(), a2.ID(), b1.ID()})
149		})
150	
151		// 对称情形：刚具备条件的甲2 标识更大时排在乙1 后，也不能固定靠前。
152		t.Run("newly eligible loses tie by larger id", func(t *testing.T) {
153			n, _ := newTestNode(t, keys, 4)
154			a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 100, 100)
155			b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
156			a2 := craftTxWithID(t, keys[0].priv, 2, 50, b1.ID(), false)
157			for _, tx := range []*Transaction{a1, a2, b1} {
158				if _, err := n.Submit(tx); err != nil {
159					t.Fatal(err)
160				}
161			}
162			assertProposalOrder(t, n, []string{a1.ID(), b1.ID(), a2.ID()})
163		})
164	
165		// 甲2 与甲1 同费用且标识更小，但甲1 未选入前甲2 不具备条件：
166		// 不能凭较小标识提前占位，顺序必须是 乙1、甲1、甲2。
167		t.Run("not yet eligible cannot preempt by smaller id", func(t *testing.T) {
168			n, _ := newTestNode(t, keys, 4)
169			b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 60, 100)
170			a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 50, 100)
171			a2 := craftTxWithID(t, keys[0].priv, 2, 50, a1.ID(), true)
172			for _, tx := range []*Transaction{a1, a2, b1} {
173				if _, err := n.Submit(tx); err != nil {
174					t.Fatal(err)
175				}
176			}
177			assertProposalOrder(t, n, []string{b1.ID(), a1.ID(), a2.ID()})
178		})
179	}
180	
181	// 相同有效交易集合、相同轮次与配置：提议产生前调整提交顺序，
182	// 最终交易顺序与区块标识不变（无替换、无容量淘汰）。
183	func TestProposeIndependentOfSubmissionOrder(t *testing.T) {
184		keys := genKeys(t, 4)
185		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 30, 100)
186		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100)
187		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
188		b2 := NewTransaction(keys[1].priv, 2, []byte("b2"), 20, 100)
189		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 50, 100) // 与 b1 同费用，考验字典序
190		set := []*Transaction{a1, a2, b1, b2, c1}
191	
192		build := func(order []*Transaction) (ProposalView, Block) {
193			n, _ := newTestNode(t, keys, 4)
194			for _, tx := range order {
195				if _, err := n.Submit(tx); err != nil {
196					t.Fatal(err)
197				}
198			}
199			p, err := n.Propose()
200			if err != nil {
201				t.Fatal(err)
202			}
203			confirmByVotes(t, n, keys, p.BlockID)
204			b, err := n.BlockAt(1)
205			if err != nil {
206				t.Fatal(err)
207			}
208			return p, b
209		}
210	
211		pFwd, bFwd := build(set)
212		pRev, bRev := build([]*Transaction{c1, b2, b1, a2, a1})
213		if fmt.Sprint(pFwd.TxIDs) != fmt.Sprint(pRev.TxIDs) {
214			t.Fatalf("submission order changed proposal order:\n%v\n%v", pFwd.TxIDs, pRev.TxIDs)
215		}
216		if pFwd.BlockID != pRev.BlockID {
217			t.Fatalf("submission order changed block id:\n%s\n%s", pFwd.BlockID, pRev.BlockID)
218		}
219		if len(pFwd.TxIDs) != 4 {
220			t.Fatalf("proposal should pack 4 transactions, got %v", pFwd.TxIDs)
221		}
222		// 确认后的历史同样一致。
223		if bFwd.ID != bRev.ID || fmt.Sprint(bFwd.TxIDs) != fmt.Sprint(bRev.TxIDs) {
224			t.Fatal("confirmed history differs between submission orders")
225		}
226	}
227	
228	// 序号缺口边界：缺少下一条应确认交易时，更高序号无论费用多高都不能入选，
229	// 其他账户照常竞争；没有任何账户提供可选交易时产生空块。
230	func TestProposeSequenceGapBoundary(t *testing.T) {
231		keys := genKeys(t, 4)
232	
233		// 甲缺序号 1，序号 2 费用再高也不能入选；乙的序号 1 照常竞争入选。
234		t.Run("gap blocks high fee successor", func(t *testing.T) {
235			n, _ := newTestNode(t, keys, 4)
236			a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 1000, 100)
237			b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 1, 100)
238			for _, tx := range []*Transaction{a2, b1} {
239				if _, err := n.Submit(tx); err != nil {
240					t.Fatal(err)
241				}
242			}
243			assertProposalOrder(t, n, []string{b1.ID()})
244			// 甲2 仍在池中等待缺口，账户查询指出最早缺口序号 1。
245			acct := n.Account(keys[0].pub)
246			if acct.Gap != 1 || len(acct.Pending) != 1 || acct.Pending[0].ID != a2.ID() {
247				t.Fatalf("gap account state wrong: %+v", acct)
248			}
249			if acct.Pending[0].Note != "waiting-pack" {
250				t.Fatalf("a2 note = %q, want waiting-pack", acct.Pending[0].Note)
251			}
252		})
253	
254		// 所有账户都缺下一条：即使池中还有等待缺口的交易，也产生空块。
255		t.Run("no eligible tx yields empty block", func(t *testing.T) {
256			n, _ := newTestNode(t, keys, 4)
257			a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 1000, 100)
258			b3 := NewTransaction(keys[1].priv, 3, []byte("b3"), 999, 100)
259			for _, tx := range []*Transaction{a2, b3} {
260				if _, err := n.Submit(tx); err != nil {
261					t.Fatal(err)
262				}
263			}
264			p := assertProposalOrder(t, n, []string{})
265			if !p.Empty {
266				t.Fatalf("proposal should be empty, got %v", p.TxIDs)
267			}
268			if wantID := BlockID(1, 1, "", []string{}); p.BlockID != wantID {
269				t.Fatalf("empty block id = %s, want %s", p.BlockID, wantID)
270			}
271			// 等待缺口的交易保持排队，已确认序号不被提议推进。
272			assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{a2.ID(): "waiting-pack"})
273			assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{b3.ID(): "waiting-pack"})
274		})
275	}
276	
277	// 已确认序号不为 0 的账户从其下一序号开始参与打包，不能重新从 1 取交易。
278	func TestProposeStartsAfterConfirmedSequence(t *testing.T) {
279		keys := genKeys(t, 4)
280		n, _ := newTestNode(t, keys, 4)
281	
282		// 第一轮：确认甲的序号 1、2，使其已确认序号变为 2。
283		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
284		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 20, 100)
285		for _, tx := range []*Transaction{a1, a2} {
286			if _, err := n.Submit(tx); err != nil {
287				t.Fatal(err)
288			}
289		}
290		p1 := assertProposalOrder(t, n, []string{a1.ID(), a2.ID()})
291		confirmByVotes(t, n, keys, p1.BlockID)
292		if acct := n.Account(keys[0].pub); acct.ConfirmedSequence != 2 {
293			t.Fatalf("confirmed sequence = %d, want 2", acct.ConfirmedSequence)
294		}
295	
296		// 第二轮：甲的序号 3、4 与乙的序号 1 竞争。甲3 费用 10、甲4 费用 100、乙1 费用 50。
297		// 甲必须从序号 3 开始：顺序为 乙1(50)、甲3(10)、甲4(100 待甲3 入选后才可参与)。
298		a3 := NewTransaction(keys[0].priv, 3, []byte("a3"), 10, 100)
299		a4 := NewTransaction(keys[0].priv, 4, []byte("a4"), 100, 100)
300		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
301		for _, tx := range []*Transaction{a3, a4, b1} {
302			if _, err := n.Submit(tx); err != nil {
303				t.Fatal(err)
304			}
305		}
306		want := []string{b1.ID(), a3.ID(), a4.ID()}
307		p2 := assertProposalOrder(t, n, want)
308		// 第二轮的区块标识接在第一个确认块之后。
309		if wantID := BlockID(2, 2, p1.BlockID, want); p2.BlockID != wantID {
310			t.Fatalf("block id = %s, want %s", p2.BlockID, wantID)
311		}
312		// 提议不推进已确认序号：甲仍为 2，乙仍为 0。
313		assertAccountQueue(t, n, keys[0].pub, 2, map[string]string{
314			a3.ID(): "waiting-vote", a4.ID(): "waiting-vote",
315		})
316		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{
317			b1.ID(): "waiting-vote",
318		})
319	}
